'use strict'

process.chdir(__dirname)

const cdpc = require('../index')

const cm = new cdpc()

cm.runChilds([
  {
    name: 'date',
    command: 'date',
    restart: 'count',
    restartDelay: 1000,
    restartLimit: 0,
    autoRemove: true,
    options: {
      stdio: ['ignore', 1, 2]
    }
  },
  {
    name: 'httpclient',
    file: 'hcli.js',
    restart: 'count',
    restartDelay: 1000,
    restartLimit: 2,
    options: {
      stdio: ['ignore', 1, 2]
    },
    after: [
      'httpserver'
    ]
  },
  
  {
    name : 'httpserver',
    file: 'app1.js',
    restart: 'always',
    restartDelay: 1000,
    options: {
      stdio: ['ignore', 1, 2]
    }
  },

  {
    name: 'uname',
    command: 'uname',
    args: [ '-a' ],
    restart: 'count',
    restartLimit: 2,
    autoRemove: true,
    options: {
      stdio: ['ignore', 1, 2]
    },
    disabled: true
  }

])

setTimeout(() => {
  console.log('检测date应用是否存在...')
  let a = cm.find('date')

  console.log(a ? a : 'null')
}, 4500)

console.log('15秒后暂停http server (name=httpserver)，并且在25秒后恢复服务...')

setTimeout(() => {
  console.log('httpserver paused')
  cm.pause('httpserver')
}, 15000)

setTimeout(() => {
  console.log('httpserver resume')
  cm.resume('httpserver')
}, 25000)

setTimeout(() => {
  console.log('uname enabled')
  cm.enable('uname')
  cm.start('uname')
}, 2500)

setTimeout(() => {
  console.log('测试完成，主进程退出。')
  process.exit(0)
}, 35000);

